#!/usr/bin/env python3
"""Regenerate the *_original* pptx fixtures in this directory.

These are plain output of ``matplotlib_extension.pyplot.save_pptx()``,
never opened in PowerPoint. The ``*_powerpoint_resaved.pptx`` fixtures
next to them are NOT regenerated by this script: they were produced by
hand, once, by opening each of these files in real PowerPoint for Mac
and resaving a copy. See ``README.md`` in this directory for exactly
how, and why those two files are committed binaries rather than
reproducible output.

Run this script (``uv run python tests/fixtures/powerpoint_mac/generate_originals.py``)
only when deliberately changing what the fixtures contain; if you do,
the ``*_powerpoint_resaved.pptx`` counterparts must be regenerated by
hand afterward, following README.md, or the two will no longer agree
and ``tests/test_relationship.py`` will fail.
"""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))

import matplotlib  # noqa: E402

matplotlib.use("Agg")

import matplotlib.pyplot as plt  # noqa: E402

from matplotlib_extension import pyplot as mplx  # noqa: E402

OUT_DIR = Path(__file__).resolve().parent


def _figure(title: str, color: str) -> plt.Figure:
    fig, ax = plt.subplots(figsize=(5, 3), dpi=100)
    ax.plot([0, 1, 2, 3], [0, 1, 4, 9], color=color)
    ax.set_title(title)
    return fig


def main() -> None:
    single = [_figure("macOS bridge fixture: single", "tab:blue")]
    mplx.save_pptx(single, OUT_DIR / "single_figure.pptx", mode="w")
    for fig in single:
        plt.close(fig)

    multi = [
        _figure("macOS bridge fixture: first", "tab:blue"),
        _figure("macOS bridge fixture: second", "tab:orange"),
        _figure("macOS bridge fixture: third", "tab:green"),
    ]
    mplx.save_pptx(multi, OUT_DIR / "multi_figure.pptx", mode="w")
    for fig in multi:
        plt.close(fig)

    print(f"Wrote single_figure.pptx and multi_figure.pptx to {OUT_DIR}")


if __name__ == "__main__":
    main()
